contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, uint bonusAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= bonusAmount);
        // First claim for this recipient is expected to succeed and pay 100 wei.
        c.getFirstWithdrawalBonus(recipient); if (__ESBMC_reverted()) return;
        uint balanceAfterFirst = address(recipient).balance;
        // A second claim for the same recipient must revert and must not pay more Ether.
        bool secondClaimReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            secondClaimReverted = true;
        } else {
            secondClaimReverted = false;
        }
        assert(secondClaimReverted && address(recipient).balance == balanceAfterFirst);
    }

    receive() external payable {}
}

